// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? '';
const text = typeof csvRaw === "string" ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};

  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // Normaliza o campo minimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// 1. Recuperar os dados recebidos pelo Merge
const entrada = $input.first().json;

const clientes = entrada.body?.clientes ?? entrada.clientes ?? [];
const investimentos = entrada.investimentos ?? [];

// Verificar se os dados recebidos estão no formato esperado
if (!Array.isArray(clientes) || !Array.isArray(investimentos)) {
  throw new Error("Não foi possível encontrar a lista de clientes ou investimentos.");
}

// 2. Converter valores monetários brasileiros para números
function converterMoeda(valor) {
  if (typeof valor === "number") {
    return valor;
  }

  const texto = String(valor ?? "")
    .trim()
    .replace(/^R\$\s*/i, "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.-]/g, "");

  const numero = Number(texto);

  return Number.isFinite(numero) ? numero : 0;
}

// 3. Converter rentabilidade para número, quando possível
function converterRentabilidade(valor) {
  const texto = String(valor ?? "")
    .trim()
    .replace("%", "")
    .replace(",", ".");

  const numero = Number(texto);

  return Number.isFinite(numero) ? numero : null;
}

// 4. Formatar valores em reais para as mensagens
function formatarMoeda(valor) {
  return Number(valor).toLocaleString("pt-BR", {
    style: "currency",
    currency: "BRL"
  });
}

// 5. Escolher aleatoriamente uma mensagem
function pick(lista) {
  return lista[Math.floor(Math.random() * lista.length)];
}

// 6. Processar cada cliente
const resultados = clientes.map(cliente => {
  const nome = String(cliente.nome ?? "Cliente").trim();
  const email = String(cliente.email ?? "").trim();
  const perfil = String(cliente.perfil ?? "").trim();
  const saldoTexto = String(cliente.saldo ?? "");
  const saldoNum = converterMoeda(cliente.saldo);

  // Buscar investimentos compatíveis com o perfil e o saldo do cliente
  const elegiveis = investimentos
    .filter(investimento => {
      const mesmoPerfil =
        String(investimento.perfil ?? "").trim().toLowerCase() ===
        perfil.toLowerCase();

      const minimo = converterMoeda(investimento.minimo);

      return mesmoPerfil && minimo <= saldoNum;
    })
    .sort((a, b) => {
      const taxaA = converterRentabilidade(a.rentabilidade);
      const taxaB = converterRentabilidade(b.rentabilidade);

      // Rentabilidades não numéricas ficam depois das numéricas
      if (taxaA === null && taxaB === null) return 0;
      if (taxaA === null) return 1;
      if (taxaB === null) return -1;

      return taxaB - taxaA;
    });

  // Selecionar a primeira opção elegível após a ordenação
  const escolhido = elegiveis[0] ?? null;

  let motivo;
  let mensagens;

  if (escolhido) {
    const minimo = converterMoeda(escolhido.minimo);
    const taxa = escolhido.rentabilidade ?? "não informada";

    motivo =
      `A opção ${escolhido.produto} está cadastrada para o perfil ` +
      `${perfil} e possui aplicação mínima compatível com o saldo informado.`;

    mensagens = [
      `Olá, ${nome}! Nossa simulação identificou ${escolhido.produto} como uma opção compatível com o perfil ${perfil}. O valor mínimo cadastrado é ${formatarMoeda(minimo)} e a rentabilidade informada na base é ${taxa}. Esta é uma simulação educacional, não uma recomendação financeira personalizada.`,

      `Olá, ${nome}! Considerando o perfil ${perfil} e o saldo informado de ${saldoTexto}, encontramos ${escolhido.produto} entre as opções elegíveis da nossa base de dados. A aplicação mínima cadastrada é ${formatarMoeda(minimo)}. Esta mensagem foi gerada por uma simulação educacional.`,

      `Oi, ${nome}! A análise automatizada identificou ${escolhido.produto} como uma alternativa cadastrada para o perfil ${perfil}. A rentabilidade registrada na base é ${taxa}, e o valor mínimo informado é ${formatarMoeda(minimo)}. Avalie as características e os riscos antes de tomar qualquer decisão financeira.`
    ];

  } else {
    motivo =
      `Não foi encontrada uma opção cadastrada para o perfil ${perfil} ` +
      `cujo investimento mínimo seja compatível com o saldo informado.`;

    mensagens = [
      `Olá, ${nome}! No momento, nossa simulação não encontrou uma opção de investimento compatível com o perfil ${perfil} e o saldo informado de ${saldoTexto}. Isso não significa que não existam outras alternativas no mercado.`,

      `Olá, ${nome}! A base de dados utilizada pelo sistema não possui uma opção elegível para o perfil ${perfil} com o saldo informado. Podemos revisar os dados e as opções cadastradas.`,

      `Oi, ${nome}! Não identificamos uma opção elegível na base de demonstração para o perfil ${perfil}. A ausência de resultados depende das opções cadastradas e não representa uma avaliação completa do mercado financeiro.`
    ];
  }

  return {
    nome,
    email,
    perfil,
    saldo_texto: saldoTexto,
    saldo_num: saldoNum,
    recomendacao: escolhido,
    motivo,
    mensagens,
    mensagem_escolhida: pick(mensagens)
  };
});

// 7. Retornar os resultados para os próximos nós do workflow
return [
  {
    json: {
      ok: true,
      total_clientes: resultados.length,
      total_investimentos: investimentos.length,
      resultados
    }
  }
];

// 1. Receber os resultados do nó anterior
const entrada = $input.first().json;
const resultados = entrada.resultados;

// Verificar se os resultados estão no formato esperado
if (!Array.isArray(resultados)) {
  throw new Error(
    "Não foi encontrada uma lista de resultados no nó anterior."
  );
}

// 2. Funções para limpar e normalizar os dados
function limparTexto(valor) {
  return String(valor ?? "").trim();
}

function converterNumero(valor) {
  if (typeof valor === "number" && Number.isFinite(valor)) {
    return valor;
  }

  const texto = String(valor ?? "")
    .trim()
    .replace(/^R\$\s*/i, "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.-]/g, "");

  if (!texto) {
    return null;
  }

  const numero = Number(texto);

  return Number.isFinite(numero) ? numero : null;
}

// 3. Preparar os dados de cada cliente
const dadosPreparados = resultados.map((resultado, indice) => {
  const nome = limparTexto(resultado.nome);
  const email = limparTexto(resultado.email);
  const perfil = limparTexto(resultado.perfil);
  const saldoTexto = limparTexto(resultado.saldo_texto);

  const saldoNumero = converterNumero(
    resultado.saldo_num ?? saldoTexto
  );

  // Limpar os dados do investimento selecionado
  let investimento = null;

  if (
    resultado.recomendacao &&
    typeof resultado.recomendacao === "object"
  ) {
    const recomendacao = resultado.recomendacao;

    investimento = {
      produto: limparTexto(recomendacao.produto),
      perfil: limparTexto(recomendacao.perfil),
      minimo: converterNumero(recomendacao.minimo),
      rentabilidade: limparTexto(recomendacao.rentabilidade)
    };
  }

  // Preparar apenas as informações necessárias para a IA
  const contextoIA = {
    cliente: nome,
    perfil_investidor: perfil,
    saldo_informado: saldoTexto,
    investimento_selecionado: investimento,
    motivo_selecao: limparTexto(resultado.motivo)
  };

  // 4. Criar as instruções que serão enviadas à IA
  const promptIA = `
Você é um assistente que redige mensagens informativas
sobre uma simulação educacional de investimentos.

Sua tarefa é criar uma mensagem personalizada para o cliente,
utilizando exclusivamente os dados fornecidos abaixo.

REGRAS:
- Escreva em português brasileiro.
- Utilize um tom cordial, natural e profissional.
- Produza uma mensagem curta, com aproximadamente 50 a 100 palavras.
- Não invente produtos, valores, taxas ou informações.
- Não prometa ganhos nem trate rentabilidades como garantidas.
- Não transforme a simulação em uma recomendação financeira
  personalizada.
- Não inclua o endereço de e-mail do cliente na mensagem.
- Se não houver investimento selecionado, informe que a base
  consultada não encontrou uma opção elegível para esta simulação.
- Se houver investimento selecionado, explique a opção utilizando
  somente os dados fornecidos.
- Retorne apenas o texto da mensagem, sem introduções adicionais,
  títulos ou explicações sobre o processo.

DADOS DO CLIENTE:
${JSON.stringify(contextoIA, null, 2)}
`.trim();

  // 5. Retornar um item organizado para cada cliente
  return {
    json: {
      cliente_id: indice + 1,
      nome,
      email,
      perfil,
      saldo_texto: saldoTexto,
      saldo_num: saldoNumero,
      investimento_selecionado: investimento,
      motivo_selecao: contextoIA.motivo_selecao,
      dados_para_ia: contextoIA,
      prompt_ia: promptIA
    },
    pairedItem: {
      item: 0
    }
  };
});

// 6. Entregar os itens preparados ao próximo nó
return dadosPreparados;

// 1. Receber as respostas do nó anterior
const items = $input.all();

// Recuperar os dados originais dos clientes.
// O nome precisa corresponder exatamente ao nome do nó no seu workflow.
let clientesOriginais = [];

try {
  clientesOriginais = $("Limpa as informações").all();
} catch (error) {
  clientesOriginais = [];
}

// 2. Funções auxiliares
function limparTexto(valor) {
  return String(valor ?? "")
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .trim();
}

function extrairTexto(valor) {
  if (typeof valor === "string") {
    return valor;
  }

  if (Array.isArray(valor)) {
    return valor
      .map(parte => extrairTexto(parte))
      .filter(Boolean)
      .join("\n");
  }

  if (valor && typeof valor === "object") {
    if (typeof valor.text === "string") {
      return valor.text;
    }

    if (typeof valor.content === "string") {
      return valor.content;
    }

    if (Array.isArray(valor.content)) {
      return extrairTexto(valor.content);
    }
  }

  return "";
}

// 3. Extrair a resposta da IA
function extrairResposta(json) {
  const candidatos = [
    json.text,
    json.output_text,
    json.response,
    json.content,
    json.message?.content,
    json.choices?.[0]?.message?.content,
    json.output?.[0]?.content,
    json.output,
    json.result
  ];

  for (const candidato of candidatos) {
    const texto = extrairTexto(candidato);

    if (texto.trim()) {
      return texto.trim();
    }
  }

  throw new Error(
    "Não foi possível localizar o texto produzido pela IA. " +
    "Confira o formato de saída do nó Message a Model."
  );
}

// 4. Interpretar o JSON produzido pela IA
function interpretarJSON(texto) {
  // Remove cercas Markdown, caso a IA as tenha incluído.
  let limpo = texto
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  try {
    return JSON.parse(limpo);
  } catch (erro) {
    // Tenta localizar um objeto JSON dentro do texto.
    const inicio = limpo.indexOf("{");
    const fim = limpo.lastIndexOf("}");

    if (inicio !== -1 && fim > inicio) {
      return JSON.parse(limpo.slice(inicio, fim + 1));
    }

    throw new Error(
      "A resposta da IA não contém um JSON válido."
    );
  }
}

// 5. Validar e normalizar cada e-mail
const saida = items.map((item, index) => {
  const respostaBruta = extrairResposta(item.json);
  const emailIA = interpretarJSON(respostaBruta);

  // Buscar o destinatário nos dados originais.
  // O endereço original prevalece sobre o informado pela IA.
  const original = clientesOriginais[index]?.json ?? item.json;

  const destinatario = limparTexto(
    original.email_to ??
    original.email ??
    original.to ??
    emailIA.to ??
    emailIA.email_to
  );

  let assunto = limparTexto(
    emailIA.subject ?? emailIA.assunto
  );

  let corpo = limparTexto(
    emailIA.text_body ??
    emailIA.textBody ??
    emailIA.body ??
    emailIA.mensagem
  );

  const erros = [];

  // 6. Validar o destinatário
  const emailValido =
    /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(destinatario);

  if (!emailValido) {
    erros.push("Destinatário ausente ou com formato inválido.");
  }

  // 7. Normalizar o assunto
  assunto = assunto
    .replace(/^assunto\s*:\s*/i, "")
    .replace(/[\r\n]+/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 120);

  if (!assunto) {
    erros.push("O assunto do e-mail está vazio.");
  }

  // 8. Normalizar o corpo em texto
  corpo = corpo
    .replace(/^corpo\s*:\s*/i, "")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();

  if (!corpo) {
    erros.push("O corpo do e-mail está vazio.");
  }

  // 9. Verificar promessas ou afirmações financeiras absolutas
  const regrasProibidas = [
    /\bganhos?\s+garantidos?\b/i,
    /\brentabilidade\s+garantida\b/i,
    /\bretorno\s+garantido\b/i,
    /\blucro\s+garantido\b/i,
    /\blucro\s+certo\b/i,
    /\bretorno\s+certo\b/i,
    /\bsem\s+risco\b/i,
    /\bgarantimos\s+(?:seus?\s+)?ganhos?\b/i,
    /\bvocê\s+vai\s+ganhar\s+(?:dinheiro|lucro)\b/i
  ];

  const frasesProblematicas = regrasProibidas
    .filter(regra => regra.test(corpo));

  if (frasesProblematicas.length > 0) {
    erros.push(
      "O texto contém uma possível promessa de ganho ou afirmação financeira absoluta. Revisão humana necessária."
    );
  }

  // 10. Garantir um aviso informativo no e-mail
  const aviso =
    "Esta mensagem apresenta uma simulação informativa, " +
    "não uma recomendação financeira personalizada. " +
    "As rentabilidades informadas não garantem resultados futuros.";

  if (
    !/não.{0,50}(?:garantia|garantem|garantido|garantida)/i.test(corpo) &&
    !/não constitui.{0,40}recomendação financeira/i.test(corpo)
  ) {
    corpo = `${corpo}\n\n${aviso}`.trim();
  }

  // 11. Gerar HTML seguro a partir do texto normalizado
  function escaparHTML(texto) {
    return texto
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  }

  const html = corpo
    .split(/\n{2,}/)
    .map(paragrafo => `<p>${escaparHTML(paragrafo).replace(/\n/g, "<br>")}</p>`)
    .join("\n");

  // 12. Retornar os campos padronizados
  return {
    json: {
      to: destinatario,
      subject: assunto,
      text_body: corpo,
      html_body: html,
      ready_to_send: erros.length === 0,
      validation_errors: erros
    },
    pairedItem: { item: index }
  };
});

return saida;
